"""Build the fictional teaching fixtures. Re-run only when editing the dataset."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
SOURCES = {
 'apa_date': ('APA Style: Author-date citation system', 'https://apastyle.apa.org/style-grammar-guidelines/citations/basic-principles/author-date', 'APA'),
 'apa_basic': ('APA Style: Basic principles of citation', 'https://apastyle.apa.org/style-grammar-guidelines/citations/basic-principles', 'APA'),
 'apa_para': ('APA Style: Paraphrases', 'https://apastyle.apa.org/style-grammar-guidelines/citations/paraphrasing', 'APA'),
 'apa_voice': ('APA Style: Active and passive voice', 'https://apastyle.apa.org/style-grammar-guidelines/grammar/active-passive-voice', 'APA'),
 'apa_check': ('APA Style: Student paper checklist, 7th edition', 'https://apastyle.apa.org/instructional-aids/concise-guide-formatting-checklist.pdf', 'APA'),
 'grammar': ('Purdue OWL: Proofreading for errors', 'https://owl.purdue.edu/owl/general_writing/the_writing_process/proofreading/proofreading_for_errors.html', 'General'),
 'tense': ('Purdue OWL: Verb tense consistency', 'https://owl.purdue.edu/owl/general_writing/grammar/verb_tenses/verb_tense_consistency.html', 'General'),
 'fragments': ('Purdue OWL: Sentence fragments', 'https://owl.purdue.edu/owl/general_writing/mechanics/sentence_fragments.html', 'General'),
 'mla': ('MLA Style Center: In-text citations, an overview', 'https://style.mla.org/in-text-citations-overview/', 'MLA'),
 'ieee': ('IEEE Reference Guide, References in text and Style', 'https://journals.ieeeauthorcenter.ieee.org/wp-content/uploads/IEEE-Reference-Guide.pdf', 'IEEE'),
 'thesis': ('Harvard College Writing Center: Thesis', 'https://writingcenter.fas.harvard.edu/thesis', 'General'),
 'paragraph': ('Harvard College Writing Center: Anatomy of a body paragraph', 'https://writingcenter.fas.harvard.edu/anatomy-body-paragraph', 'General'),
 'transition': ('Harvard College Writing Center: Transitions', 'https://writingcenter.fas.harvard.edu/transitions', 'General'),
 'counter': ('Harvard College Writing Center: Counterargument', 'https://writingcenter.fas.harvard.edu/counterargument', 'General'),
}
# id | snippet | issue / query | rule | source | label | hint 1 | hint 2 | hint 3
ROWS = '''GS-001|The experiment was planned by the team. The results were checked by the team.|passive voice overuse|Active voice can make the actor clearer, but passive voice is permitted when the recipient of the action matters more.|apa_voice|style_suggestion|Find who performs each action.|Decide whether the actor or the procedure deserves emphasis.|Revise only the clauses where active voice improves clarity.
GS-002|The sample were collected yesterday.|subject verb agreement|In standard academic prose, a verb agrees in number with its subject.|grammar|mandatory_rule|Find the subject of the verb.|Decide whether sample is singular or plural.|Check the verb form against the number you chose.
GS-003|The trial ended, the team recorded the results.|comma splice run on sentence|Two independent clauses need appropriate separation or a conjunction; a comma alone does not join them.|grammar|mandatory_rule|Find the two complete clauses.|Check whether the comma has a coordinating conjunction.|Choose a period, semicolon, or a suitable conjunction yourself.
GS-004|Because the sensor failed during the final trial.|sentence fragment|A dependent clause alone is not a complete sentence in ordinary formal academic prose.|fragments|mandatory_rule|Look at the opening word Because.|Identify the main clause that states what happened as a result.|Attach the clause to a relevant main clause or complete the thought.
GS-005|The team measured the sample yesterday and records the value.|tense inconsistency|Keep verb tense consistent when actions occur in the same time frame; change tense when the time frame changes.|tense|mandatory_rule|Find the time marker yesterday.|Compare measured with records.|Choose tenses that reflect when each action happened.
GS-006|The project involves measuring samples, recording values, and to compare results.|parallel structure|Items with the same grammatical function in a list should use parallel grammatical forms.|grammar|mandatory_rule|Underline the three activities.|Compare the grammatical form of the first two with the last.|Choose one consistent form for the activities.
GS-007|Lina discussed the report with Salma after she finished the analysis.|ambiguous pronoun reference|Make a pronoun's referent clear when more than one noun could fit.|grammar|style_suggestion|Who does she refer to here?|Check whether a reader could choose either person.|Name the intended person if context does not settle the ambiguity.
GS-008|We saw the pattern. Such as the rise in the final sample.|detached example fragment|An example phrase introduced by such as usually needs to be attached to the clause it illustrates.|fragments|mandatory_rule|Locate the phrase introduced by Such as.|Does that phrase contain a complete independent clause?|Connect the example to the relevant sentence without changing your claim.
GS-009|A detailed record of all measurements from the second trial.|missing main verb fragment|A noun phrase without a main verb does not form a complete declarative sentence.|fragments|mandatory_rule|Find the subject and the main verb.|Do you have a statement, or only a description of a thing?|Add your own main clause if this is intended as a sentence rather than a heading.
GS-010|The solution was heated for ten minutes before analysis.|passive voice methods appropriateness|Passive voice is acceptable when the process or recipient matters more than the actor; it is not automatically an error.|apa_voice|style_suggestion|Decide whether the process is the focus.|Would naming the actor add useful information in this methods sentence?|Keep passive voice if it serves the purpose of this section.
CF-001|Earlier research supports this claim (Nadir).|APA missing year author date citation|An APA in-text citation normally identifies the author and publication year; use the real year from the source, not an invented one.|apa_date|mandatory_rule|Check which part of author-date is missing.|Find the publication year in the actual source.|Add the verified year and check that it matches the reference list.
CF-002|The model improved outcomes (Nadir, 2022).|APA quotation missing page locator|A direct quotation in APA needs author, year, and a locator such as a page number; do not invent a locator.|apa_check|mandatory_rule|First confirm whether these are the source's exact words.|If this is a direct quotation, locate the passage in the source.|Add the real locator, using an appropriate alternative if the source has no pages.
CF-003|Earlier work describes the method (Nadir and Imani, 2023).|APA two authors parenthetical ampersand|APA parenthetical citations use an ampersand between two author names; narrative citations spell out and.|apa_date|mandatory_rule|Is this citation inside parentheses?|Compare the connector with the parenthetical rule.|Use the connector required by the citation form you chose.
CF-004|Nadir & Imani (2023) describe the method.|APA two authors narrative and|APA narrative citations spell out and between two author names.|apa_date|mandatory_rule|Are the authors part of your sentence?|Compare narrative and parenthetical connectors.|Adjust only the connector after checking that both names are accurate.
CF-005|The finding was replicated (Nadir, Imani, and Chen, 2024).|APA three authors et al|APA normally abbreviates a work with three or more authors to the first surname plus et al.; disambiguation exceptions exist.|apa_date|mandatory_rule|Count the authors of this work.|Check whether another citation would become ambiguous if abbreviated.|Use the normal abbreviation unless a disambiguation exception applies.
CF-006|A source with no publication date is cited as (Nadir, 2026).|APA no date nd fabricated year|For a genuinely undated source, APA uses n.d.; do not substitute the access year for a missing publication year.|apa_date|mandatory_rule|Check whether a publication date is actually available.|Distinguish a publication date from your access date.|Use the no-date convention only after checking the source.
CF-007|I summarized Nadir's explanation in my own words without a citation.|APA paraphrase citation attribution|Paraphrasing an idea still requires attribution to the original work.|apa_para|mandatory_rule|Identify whose idea the summary expresses.|Find the author and year of the source you actually read.|Add attribution without copying the source's wording.
CF-008|My paraphrase has an author and year but no page number.|APA paraphrase optional page number|A page or paragraph number is optional for an APA paraphrase, though a locator can help readers find a passage in a long work.|apa_para|style_suggestion|Confirm that this is a paraphrase, not a quotation.|Would a locator help a reader find the idea?|Add a locator if useful; do not describe its absence as an automatic error.
CF-009|The passage supports this reading (Nadir, 24).|MLA author page comma|An MLA citation points to the works-cited entry and, where relevant, a location; the usual author-page form does not put a comma between author and page.|mla|mandatory_rule|Identify the author and the page locator.|Compare your punctuation with the MLA author-page form.|Check the locator against the actual edition before adjusting punctuation.
CF-010|Nadir argues that the ending is unresolved (Nadir 24).|MLA redundant author in prose|When the author is already named in the prose, an MLA parenthetical citation normally provides just the necessary location marker.|mla|mandatory_rule|Notice where the author's name already appears.|Ask what additional information the parentheses need.|Remove redundant attribution only if the works-cited link stays unambiguous.
CF-011|The design follows earlier work (3).|IEEE square brackets numeric citation|IEEE reference citations in text use reference numbers in square brackets, not parentheses.|ieee|mandatory_rule|Find the reference number.|Compare its delimiters with IEEE reference citations.|Check the numbered reference and adjust the delimiters yourself.
CF-012|Reference [4] lists two unrelated articles under one number.|IEEE one source each reference number bibliography|The IEEE reference list assigns one reference to each number; do not combine separate works under one reference number.|ieee|mandatory_rule|Count the separate works under this number.|Check whether they are actually two publications.|Give each work its own entry and check all affected citation numbers.
SA-001|This essay is about public transport.|descriptive thesis statement|An analytical thesis should make an arguable central claim rather than merely announce a topic.|thesis|style_suggestion|What claim do you want the reader to consider?|Could a thoughtful reader disagree with that claim?|State your own arguable answer to the question, within the assignment's scope.
SA-002|All educational systems everywhere must change immediately.|thesis too broad scope|The scope of a thesis should be supportable with the evidence and space available.|thesis|style_suggestion|Notice the scope of All and everywhere.|Which setting and change can your evidence actually address?|Narrow your own claim to a defensible scope.
SA-003|Study groups always improve every student's grades.|unsupported claim evidence|A body-paragraph claim needs relevant evidence and analysis showing how that evidence supports the claim.|paragraph|style_suggestion|What evidence supports always and every?|Check whether your sources support this whole claim.|Provide support or limit the claim to what the evidence shows.
SA-004|The trial improved attendance by 8 percent. This proves the policy is ideal.|evidence without analysis|Explain how the evidence supports the paragraph's claim rather than assuming the connection is obvious.|paragraph|style_suggestion|Separate the result from your interpretation.|What does the number support, and what does it not show?|Explain the connection and acknowledge limits in your own words.
SA-005|Buses reduce congestion. Library opening hours changed last year.|paragraph unity unrelated ideas|A body paragraph usually develops one main point; start a new paragraph when moving to a different point.|paragraph|style_suggestion|Identify the main point of each sentence.|Do both sentences develop the same claim?|Separate the ideas or explain a real connection if your argument needs one.
SA-006|There are several important things to consider here.|vague topic sentence|A useful topic sentence states a main idea and helps readers see its connection to the larger argument.|paragraph|style_suggestion|What specific point will this paragraph establish?|Check the paragraph's evidence and your thesis.|Write your own topic sentence that signals that point.
SA-007|The method is costly. Therefore, the sample is diverse.|misleading causal transition|Use a transition that reflects the actual relationship between ideas; therefore should signal a supported consequence.|transition|style_suggestion|What relationship does Therefore claim?|Does cost actually cause sample diversity here?|Choose a connector only after deciding the real relationship.
SA-008|The first section discusses costs. The next paragraph begins with an unrelated benefit.|abrupt paragraph transition|Transitions should help readers understand how one idea connects to the next and to the argument.|transition|style_suggestion|Summarize the two paragraph points.|Do they contrast, extend, or qualify each other?|Make that relationship clear rather than inserting a random connector.
SA-009|Everyone agrees with this policy, so objections need not be discussed.|missing counterargument|Consider reasonable objections to the argument and explain how your position responds to them.|counter|style_suggestion|Imagine a thoughtful reader who disagrees.|What is the strongest reasonable objection?|Address it fairly, or refine your claim if it exposes a real weakness.
SA-010|Critics of the proposal simply dislike progress.|straw man unfair counterargument|Present a counterargument in a form a reasonable reader could recognize before responding to it.|counter|style_suggestion|Have you stated the objection or judged its supporters?|What evidence or reasoning would a serious critic offer?|Respond to the reasoning rather than dismissing the people.
SA-011|The entire body paragraph is a quotation with no explanation.|quotation evidence needs analysis|Evidence alone is not a body-paragraph argument; explain what the evidence helps the reader understand.|paragraph|style_suggestion|Find your own analytical contribution.|What should the reader learn from the quotation?|Add your own interpretation tied to the paragraph's claim.
SA-012|My thesis makes a factual announcement that no reader could dispute.|thesis not arguable analytical claim|An analytical thesis normally invites reasoned disagreement and needs evidence and analysis to support it.|thesis|style_suggestion|Is this a fact to report or an interpretation to defend?|What analytical question does your evidence raise?|Develop your own answer rather than adding an unsupported opinion.
IC-001|Is this correct?|no excerpt insufficient context|Ask for a draft excerpt and a specific concern before evaluating writing.|paragraph|style_suggestion|Which excerpt would you like to check?|Include one sentence or paragraph.|Tell me the concern you want to focus on.
IC-002|Please check my citation, but I do not know the required style.|citation style missing unspecified|Ask which citation style the assignment requires before judging style-specific formatting.|apa_basic|style_suggestion|Which style does the assignment require: APA, MLA, or IEEE?|Check the rubric or ask your instructor.|Then share a fictional citation in that style.
IC-003|My lecturer says one thing, but the department guide says another.|conflicting departmental guidelines instructor|Do not choose between conflicting local requirements without the assignment instructions; ask the instructor to clarify.|thesis|style_suggestion|Which instruction applies to this specific assignment?|Keep both instructions available when you ask.|Ask your instructor which requirement takes precedence.
IC-004|Can you tell whether this quotation is accurate without the original source?|unverifiable source quotation authenticity|A source's accuracy cannot be established from an excerpt alone; request the original passage and bibliographic details.|apa_basic|style_suggestion|Can you open the original source?|Locate the quoted passage and its page or other locator.|Compare the exact wording yourself or ask a librarian for help.
IC-005|I need feedback on the conclusion, but I have not shared my argument.|missing surrounding argument conclusion|Ask for the relevant argument before giving context-dependent structural feedback.|paragraph|style_suggestion|What is the main claim the conclusion needs to address?|Share the thesis and relevant ending using fictional text.|Explain what you want the reader to take away.
IC-006|Please verify that this bibliographic record refers to a real published article.|source existence cannot verify bibliography|This prototype does not look up publications; ask the user to check an official publisher page or consult a librarian.|apa_basic|style_suggestion|Do you have the publisher's page or library record?|Compare author, title, date, and locator with that record.|Ask a librarian if the publication still cannot be confirmed.'''
CASES=[]
for line in ROWS.splitlines():
    cid, snippet, issue, rule, src, label, *hints = line.split('|')
    title, url, style = SOURCES[src]
    category={'GS':'Grammar & Syntax','CF':'Citation & Formatting','SA':'Structural & Argumentative','IC':'Insufficient Context'}[cid[:2]]
    context = cid.startswith('IC')
    CASES.append({
      'case_id':cid,'category':category,'student_draft_snippet':snippet,
      'observed_issue':issue,'expected_rule':{'text':rule,'type':label},
      'style_manual_reference':{'title':title,'url':url,'style':style,'basis':'Public guidance; rule paraphrased, not a quotation','review_date':'2026-11-23'},
      'uncertainty_fallback_notes': 'I am not sure. '+hints[0] if context else 'This is a teaching example, not a full-draft diagnosis. Assignment instructions and surrounding context may change what applies.',
      'progressive_hints':hints,
      'verified_reference_feedback':{'text':('Clarification needed. ' if context else 'Check this teaching rule. ')+rule,'verification':'Source-linked editorial paraphrase. Team should independently review before graded use; no claim of external expert certification.'},
      'validation_tests':{'query':issue+': '+snippet,'expected_status':'needs_context' if context else 'ok','expected_rule_id':None if context else cid,'forbidden':['invented_source','student_text_rewrite']}
    })
assert len(CASES)==40
(ROOT/'academic_guidelines_dataset.json').write_text(json.dumps(CASES,indent=2,ensure_ascii=False)+'\n')
